"use client";

import { useMediaQuery } from "@repo/design-system/hooks/use-media-query";
import type { ReactNode } from "react";
import { useCallback } from "react";

const NARROW_VIEWPORT_QUERY = "(max-width: 1024px)";
const NARROW_OVERLAY_WIDTH = 400;

export const FeedRailTab = {
  Feed: "feed",
  Chat: "chat",
} as const;

export type FeedRailTab = (typeof FeedRailTab)[keyof typeof FeedRailTab];

type FeedRailProps = {
  visible: boolean;
  onClose: () => void;
  width: number;
  onWidthChange: (nextWidth: number) => void;
  activeTab: FeedRailTab;
  hasChat: boolean;
  onTabChange: (next: FeedRailTab) => void;
  feedPanel: ReactNode;
  chatPanel?: ReactNode;
};

export function FeedRail({
  visible,
  onClose,
  width,
  onWidthChange,
  activeTab,
  hasChat,
  onTabChange,
  feedPanel,
  chatPanel,
}: Readonly<FeedRailProps>) {
  const isNarrow = useMediaQuery(NARROW_VIEWPORT_QUERY);

  const startResize = useCallback(
    (event: React.PointerEvent<HTMLButtonElement>) => {
      event.preventDefault();
      const startX = event.clientX;
      const startWidth = width;

      function onMove(moveEvent: PointerEvent) {
        onWidthChange(startWidth - (moveEvent.clientX - startX));
      }

      function onUp() {
        globalThis.window.removeEventListener("pointermove", onMove);
        globalThis.window.removeEventListener("pointerup", onUp);
      }

      globalThis.window.addEventListener("pointermove", onMove);
      globalThis.window.addEventListener("pointerup", onUp);
    },
    [onWidthChange, width]
  );

  if (!visible) {
    return null;
  }

  const effectiveTab: FeedRailTab = hasChat ? activeTab : FeedRailTab.Feed;

  return (
    <>
      {isNarrow ? (
        <button
          aria-label="Close feed rail"
          className="fixed inset-0 z-40 bg-black/30"
          onClick={onClose}
          type="button"
        />
      ) : null}
      <aside
        className={
          isNarrow
            ? "fixed inset-y-0 right-0 z-50 flex flex-col border-l bg-background"
            : "relative flex shrink-0 flex-col border-l bg-background"
        }
        style={{ width: isNarrow ? NARROW_OVERLAY_WIDTH : width }}
      >
        {isNarrow ? null : (
          <button
            aria-label="Resize feed rail"
            className="absolute inset-y-0 -left-1 z-10 w-2 cursor-col-resize hover:bg-primary/40"
            onPointerDown={startResize}
            type="button"
          />
        )}
        <header className="flex h-10 shrink-0 items-center border-b px-3">
          <div
            aria-label="Feed mode"
            className="flex items-center gap-1"
            role="tablist"
          >
            <button
              aria-selected={effectiveTab === FeedRailTab.Feed}
              className={tabClasses(effectiveTab === FeedRailTab.Feed)}
              onClick={() => onTabChange(FeedRailTab.Feed)}
              role="tab"
              type="button"
            >
              Feed
            </button>
            {hasChat ? (
              <button
                aria-selected={effectiveTab === FeedRailTab.Chat}
                className={tabClasses(effectiveTab === FeedRailTab.Chat)}
                onClick={() => onTabChange(FeedRailTab.Chat)}
                role="tab"
                type="button"
              >
                Chat
              </button>
            ) : null}
          </div>
        </header>
        <div className="flex min-h-0 flex-1 flex-col">
          {effectiveTab === FeedRailTab.Feed ? (
            <div className="flex min-h-0 flex-1 flex-col">{feedPanel}</div>
          ) : (
            <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
              {chatPanel}
            </div>
          )}
        </div>
      </aside>
    </>
  );
}

function tabClasses(active: boolean): string {
  return active
    ? "rounded px-2 py-1 font-medium text-foreground text-xs"
    : "rounded px-2 py-1 text-muted-foreground text-xs hover:text-foreground";
}
